const TIME_LIMIT: int = 2538;            // 120 buffer + 2218 local schedule + 200 tail
const TH18_FIREBALL_YELLOW: int = 800;   // type28, radius 4, native colors 0..15

// GirlA02_at HOMING (0x40000000): a=200 (E) / 800 (NHL), r=2.6, s=0, m=0.01.
// Per tick: v += (2.6 * unit(player - bullet) - v) * 0.01.
// step_vx/step_vy with frames=0 are the engine's immediate vx/vy writes; each keeps the
// other component, so the pair is the exact per-tick vector mix.  A per-bullet task
// (ex-effects HOMING row) would cost one task slot per bullet (48 enemies x 30 shots at
// L), far over the 256 task pool; xform costs none and starts on the creation frame.
xformdef HOMING_200 {
again:
    step_vx(at_effect($self_vx + (2.6fx*cos(atan2($player_y-$self_y, $player_x-$self_x)) - $self_vx)*0.01fx), 0);
    step_vy(at_effect($self_vy + (2.6fx*sin(atan2($player_y-$self_y, $player_x-$self_x)) - $self_vy)*0.01fx), 0);
    wait(1);
    loop(again, 200);
}

xformdef HOMING_800 {
again:
    step_vx(at_effect($self_vx + (2.6fx*cos(atan2($player_y-$self_y, $player_x-$self_x)) - $self_vx)*0.01fx), 0);
    step_vy(at_effect($self_vy + (2.6fx*sin(atan2($player_y-$self_y, $player_x-$self_x)) - $self_vy)*0.01fx), 0);
    wait(1);
    loop(again, 800);
}

// GirlA02_at S:216-264.  etAim(1) fixed fan, etCount 1x1, etAngle(pi/2, 100deg),
// etSpeed(3.0, 1.0) so M=1 uses 3.0.  diffI($A,1,4,5,30); waits 100/100/70/40.
async sub girl_shot() {
    wait(22);                                      // S:219
    var rank: int = global(GVAR_RANK);
    var n: int = 4;
    var gap: int = 100;
    if rank == RANK_EASY { n = 1; }
    if rank == RANK_HARD { n = 5; gap = 70; }
    if rank == RANK_LUNATIC { n = 30; gap = 40; }
    for i in 0..n {
        // S:233-245: type28 color0; HOMING a=200/800, r=2.6, s=0, m=0.01.  ANIM a=1
        // (type2, S:235) retreat is position -= 4*velocity = 12px opposite the 90deg shot.
        if rank == RANK_EASY {
            _ = fire(TH18_FIREBALL_YELLOW, 0, $self_x, $self_y-12fx, 3fx, 90deg, HOMING_200, none);
        } else {
            _ = fire(TH18_FIREBALL_YELLOW, 0, $self_x, $self_y-12fx, 3fx, 90deg, HOMING_800, none);
        }
        wait(gap);
    }
}

// GirlA02 S:208-215 -> GirlA02f S:265-282 (sync callee, never returns; delete unreachable).
async sub girl_main(mirror: int) {
    // S:267-268 setHurtbox(24,24)/setHitbox(16,16): native ordinary circle uses half.
    set_hurtbox(12fx);
    set_hitbox(8fx);
    // Training pool: zako invulnerable; source hurtbox/hitbox above are retained.
    set_invuln(65535);
    // S:271 moveVel(pi/2, 0.8); mirrored write angle pi-theta keeps 90deg.
    move_vel(0, 90deg, 0.8fx, EASE_LINEAR);
    spawn girl_shot();                             // S:272 async GirlA02_at
    wait(60);                                      // S:273
    // S:274 moveVelTime(120,1,1.1780972,0.2): mode1 = t^2 on angle and speed.
    // enmCreateM mirror flips movement write angles (not firing angles).
    var end_angle: angle = 67.5deg;
    if mirror != 0 { end_angle = 112.5deg; }
    move_vel(120, end_angle, 0.2fx, EASE_QUAD_IN);
    loop { wait(1000); }                           // S:275-280 GirlA02f tail loop
}

